/*
 * Structures. Offsets in the comments are the GameCube ones (the reference objects); they hold
 * only under __MWERKS__. On the 64-bit host every pointer slot below is 8 bytes, so the host
 * layout differs: never address a field with a GC offset or stride, and never memset/memcpy a
 * struct with a GC size (write sizeof). Fields marked HOST: pointer are the pointer slots.
 * unkXXX names carry the GC offset; "never accessed" means no access was found in the reference
 * asm (a gap filler, sized so every later field keeps its offset).
 */

/* Match-Up modes: mgMatchGameType (set by the hub mdminidll) is copied to MGMATCH_MODEWORK.gameType.
 * The minigame list lbl_1_data_C0 is laid out by mode: [0..20] 4-player, [21..31] 2 vs 2,
 * [32..42] 1 vs 3 (fn_1_85C4). */
#define MGMATCH_GAMETYPE_4P 0
#define MGMATCH_GAMETYPE_1VS3 1
#define MGMATCH_GAMETYPE_2VS2 2

/* Message file of this overlay: MESS_MGMODE_MATCH (dir 15, lis r4,0xf in mess.c) */
#define MGMATCH_MESS(file) MESSNUM(MESS_MGMODE_MATCH, (file))

/* mgmatch.c lbl_1_data_C0 (43 entries) and MGMATCH_MODEWORK.mg[]: one minigame of the list.
 * fn_1_85C4 fills mgIdx (mgDataTbl index whose .ovl == ovl) and battleF, then copies the unlocked
 * entries of the current mode into mg[] by struct assignment (3 x lhz/sth). */
typedef struct MgMatchMg_s {
    u16 ovl; /* 0x0 DLL number, compared with mgDataTbl[].ovl (cmplw) */
    s16 mgNo; /* 0x2 5xx minigame number (lha; GWMgUnlockGet argument) */
    s8 mgIdx; /* 0x4 mgDataTbl index (stb / lbz+extsb) */
    s8 battleF; /* 0x5 mgDataTbl[mgIdx].type == 3 (MG_TYPE_BATTLE), cntlzw idiom -- name a guess */
} MGMATCH_MG; /* 0x6 */

